<?php require_role('admin');$pageTitle='Departmental Analytics';$pageSubtitle='Real-time quality-assurance overview';$students=(int)(db_one("SELECT COUNT(*) c FROM users WHERE role='student' AND status='active'")['c']??0);$supervisors=(int)(db_one("SELECT COUNT(*) c FROM users WHERE role='supervisor' AND status='active'")['c']??0);$projects=(int)(db_one("SELECT COUNT(*) c FROM projects WHERE status='active'")['c']??0);$sessions=(int)(db_one("SELECT COUNT(*) c FROM sessions WHERE status='completed'")['c']??0);$projectRows=db_all("SELECT p.*,u.full_name student_name,s.full_name supervisor_name FROM projects p JOIN users u ON u.id=p.student_id LEFT JOIN users s ON s.id=p.supervisor_id ORDER BY p.id DESC");$workload=db_all("SELECT u.full_name,COUNT(p.id) total FROM users u LEFT JOIN projects p ON p.supervisor_id=u.id WHERE u.role='supervisor' GROUP BY u.id,u.full_name ORDER BY total DESC");include __DIR__.'/../includes/layout_top.php'; ?>
<div class="stats-grid"><div class="stat-card"><div class="stat-label">Active students</div><div class="stat-value"><?= $students ?></div><div class="stat-note">Registered final-year students</div></div><div class="stat-card"><div class="stat-label">Supervisors</div><div class="stat-value"><?= $supervisors ?></div><div class="stat-note">Academic staff accounts</div></div><div class="stat-card"><div class="stat-label">Active projects</div><div class="stat-value"><?= $projects ?></div><div class="stat-note">Assigned supervision records</div></div><div class="stat-card"><div class="stat-label">Completed sessions</div><div class="stat-value"><?= $sessions ?></div><div class="stat-note">Documented supervision meetings</div></div></div>
<div class="dashboard-grid"><section><div class="card"><div class="card-header"><div><h2>Cohort progress</h2><p>Students requiring attention appear with lower approved milestone percentages.</p></div></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Supervisor</th><th>Project</th><th>Stage</th><th>Progress</th></tr></thead><tbody><?php foreach($projectRows as $p):$prog=progress_for_project((int)$p['id']);?><tr><td><strong><?= e($p['student_name']) ?></strong></td><td><?= e($p['supervisor_name']?:'Unassigned') ?></td><td><?= e($p['title']) ?></td><td><?= e($p['current_stage']) ?></td><td><div class="progress-row"><span class="badge <?= $prog<35?'danger':($prog<70?'warning':'success') ?>"><?= $prog ?>%</span></div><div class="progress-track"><div class="progress-bar" data-progress="<?= $prog ?>"></div></div></td></tr><?php endforeach;?></tbody></table></div></div></section><aside><div class="card"><div class="card-header"><div><h3>Supervisor workload</h3><p>Number of assigned students</p></div></div><div class="chart-bars"><?php $max=max(array_column($workload,'total')?:[1]);foreach($workload as $w):$height=max(12,round(((int)$w['total']/$max)*170));?><div class="chart-bar" style="height:<?= $height ?>px"><b><?= (int)$w['total'] ?></b><span><?= e(explode(' ',$w['full_name'])[0]) ?></span></div><?php endforeach;?></div></div><div class="card"><div class="card-header"><h3>Quality indicators</h3></div><div class="list-card"><div><h4>Pending session requests</h4><p>Awaiting supervisor action</p></div><strong><?= (int)(db_one("SELECT COUNT(*) c FROM sessions WHERE status='requested'")['c']??0) ?></strong></div><div class="list-card"><div><h4>Submitted milestones</h4><p>Awaiting review</p></div><strong><?= (int)(db_one("SELECT COUNT(*) c FROM milestones WHERE status='submitted'")['c']??0) ?></strong></div><div class="list-card"><div><h4>Overdue open milestones</h4><p>Past due and not approved</p></div><strong><?= (int)(db_one("SELECT COUNT(*) c FROM milestones WHERE due_date<CURRENT_DATE AND status<>'approved'")['c']??0) ?></strong></div></div></aside></div>
